local conns = {}
local function connect(signal, fn)
	local c = signal:Connect(fn)
	table.insert(conns, c)
	return c
end

local function destroyAll()
	for _, c in ipairs(conns) do
		pcall(function() c:Disconnect() end)
	end
	pcall(function() Blur:Destroy() end)
	Gui:Destroy()
end

local function makeSound(id, volume)
	local s = Instance.new("Sound")
	s.SoundId = "rbxassetid://" .. id
	s.Volume = volume
	s.Parent = Gui
	return s
end
local clickSound = makeSound(CLICK_SFX, 0.6)
local hoverSound = makeSound(HOVER_SFX, 0.35)
local sliderSound = makeSound(SLIDER_SFX, 0.4)

local function playClick()
	clickSound.TimePosition = 0
	clickSound:Play()
end
local function playHover()
	hoverSound.TimePosition = 0
	hoverSound:Play()
end
local lastSlide = 0
local function playSlider()
	local now = os.clock()
	if now - lastSlide < 0.04 then return end
	lastSlide = now
	sliderSound.TimePosition = 0
	sliderSound:Play()
end

