local function build(class, defaults, props, parent)
	local o = Instance.new(class)
	for k, v in pairs(defaults) do o[k] = v end
	for k, v in pairs(props) do o[k] = v end
	o.Parent = parent
	return o
end

local function frame(p, par)
	return build("Frame", { BorderSizePixel = 0, BackgroundColor3 = COL.Panel }, p, par)
end

local function label(p, par)
	return build("TextLabel", {
		BackgroundTransparency = 1, BorderSizePixel = 0, Font = Enum.Font.Gotham,
		TextSize = 13, TextColor3 = COL.Text, Text = "",
	}, p, par)
end

local function button(p, par, noClick)
	local b = build("TextButton", {
		AutoButtonColor = false, BorderSizePixel = 0, Text = "", Font = Enum.Font.GothamMedium,
		TextSize = 13, TextColor3 = COL.Text, BackgroundColor3 = COL.Element,
	}, p, par)
	b.MouseEnter:Connect(playHover)
	if not noClick then b.MouseButton1Click:Connect(playClick) end
	return b
end

local function corner(o, r)
	return build("UICorner", { CornerRadius = UDim.new(0, r or CORNER) }, {}, o)
end

local function stroke(o, color, thickness, transparency)
	return build("UIStroke", {
		Color = color, Thickness = thickness or 1, Transparency = transparency or 0,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
	}, {}, o)
end

local function pad(o, n)
	return build("UIPadding", {
		PaddingTop = UDim.new(0, n), PaddingBottom = UDim.new(0, n),
		PaddingLeft = UDim.new(0, n), PaddingRight = UDim.new(0, n),
	}, {}, o)
end

local function listLayout(o, padding)
	return build("UIListLayout", { Padding = UDim.new(0, padding or 0), SortOrder = Enum.SortOrder.LayoutOrder }, {}, o)
end

local function tween(o, t, props)
	TweenService:Create(o, TweenInfo.new(t, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props):Play()
end

