end

local LOGO_B64 = ""

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function b64decode(data)
	local map = {}
	for i = 1, #B64 do map[B64:byte(i)] = i - 1 end
	local out, n = {}, 0
	for i = 1, #data - 3, 4 do
		local a, b, c, d = data:byte(i, i + 3)
		local v = map[a] * 262144 + map[b] * 4096 + (map[c] or 0) * 64 + (map[d] or 0)
		n += 1
		if c == 61 then
			out[n] = string.char(math.floor(v / 65536))
		elseif d == 61 then
			out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256)
		else
			out[n] = string.char(math.floor(v / 65536), math.floor(v / 256) % 256, v % 256)
		end
	end
	return table.concat(out)
end

local function logoImage()
	if LOGO_ID ~= "" then return "rbxassetid://" .. LOGO_ID end
	if getcustomasset and isfile and writefile then
		local ok, res = pcall(function()
			if LOGO_URL ~= "" and not isfile(LOGO_FILE) then
				writefile(LOGO_FILE, game:HttpGet(LOGO_URL))
			end
			if isfile(LOGO_FILE) then return getcustomasset(LOGO_FILE) end
			local embedded = "wexst_logo_white.png"
			if not isfile(embedded) then writefile(embedded, b64decode(LOGO_B64)) end
			return getcustomasset(embedded)
		end)
		if ok and res then return res end
	end
	return ""
end
local LOGO_IMAGE = logoImage()

local function buildLogo(w, h, parent, scale)
