		build("ImageLabel", {
			BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1),
			Image = LOGO_IMAGE, ScaleType = scale or Enum.ScaleType.Fit,
		}, {}, tile)
	else
		label({
			Size = UDim2.fromScale(1, 1), Text = "W", Font = Enum.Font.GothamBlack,
			TextSize = math.floor(h * 0.6), TextColor3 = COL.White,
		}, tile)
	end
	return tile
end

