local hubShown = true
local blurStrength, blurEnabled, dimOn = 12, true, true
local snowEnabled, snowCount, windScale, snowAlpha = true, 110, 1, 0

local Dim = frame({
	Name = "Dim", Size = UDim2.fromScale(1, 1), BackgroundColor3 = COL.Black,
	BackgroundTransparency = 1, ZIndex = 1,
}, Gui)

local SnowLayer = frame({
	Name = "Snow", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 2, Visible = false,
}, Gui)

local MAX_FLAKES = 140
local flakes = {}
for i = 1, MAX_FLAKES do
	local depth = math.random() ^ 1.4
	local size = 2 + math.floor(depth * 4 + 0.5)
	local f = frame({
		Size = UDim2.fromOffset(size, size), BackgroundColor3 = COL.White,
		BackgroundTransparency = 1, ZIndex = 2, Visible = false,
	}, SnowLayer)
	build("UICorner", { CornerRadius = UDim.new(0.5, 0) }, {}, f)
	flakes[i] = {
		f = f, depth = depth, base = 0.62 - depth * 0.42, init = false,
		x = math.random(), y = math.random(),
		vy = 38 + depth * 90 + math.random() * 14,
		sway = 8 + math.random() * 20, ph = math.random() * 6.283, fr = 0.5 + math.random() * 1.2,
	}
end

local function applyBackdrop(on)
	tween(Blur, 0.35, { Size = (on and blurEnabled) and blurStrength or 0 })
	tween(Dim, 0.35, { BackgroundTransparency = (on and dimOn) and 0.6 or 1 })
end

local function updateSnow(dt, t)
	local target = (hubShown and snowEnabled) and 1 or 0
	snowAlpha = snowAlpha + (target - snowAlpha) * math.min(1, dt * 5)
	if math.abs(target - snowAlpha) < 0.004 then snowAlpha = target end
	if snowAlpha <= 0 then
		if SnowLayer.Visible then SnowLayer.Visible = false end
		return
	end
	SnowLayer.Visible = true

	local vp = Gui.AbsoluteSize
	if vp.X < 10 or vp.Y < 10 then vp = Vector2.new(1920, 1080) end
	local wind = (36 + 26 * math.sin(t * 0.33) + 12 * math.sin(t * 0.91 + 1.3)) * windScale

	for i, fl in ipairs(flakes) do
		if i <= snowCount then
			if not fl.init then
				fl.x, fl.y, fl.init = fl.x * vp.X, fl.y * vp.Y, true
			end
			fl.y = fl.y + fl.vy * dt
			fl.x = fl.x + (wind * (0.35 + fl.depth * 0.9) + math.sin(t * fl.fr + fl.ph) * fl.sway) * dt
			if fl.y > vp.Y + 8 then
				fl.y = -8
				fl.x = math.random() * vp.X
			end
			if fl.x > vp.X + 8 then fl.x = -8 elseif fl.x < -8 then fl.x = vp.X + 8 end
			fl.f.Position = UDim2.fromOffset(fl.x, fl.y)
			fl.f.BackgroundTransparency = 1 - (1 - fl.base) * snowAlpha
			fl.f.Visible = true
		else
			fl.f.Visible = false
		end
	end
end

