local function Notify(title, text, duration)
	if not Settings.Notifications then return end
	local slot = frame({ Size = UDim2.new(1, 0, 0, 56), BackgroundTransparency = 1, ClipsDescendants = true }, NotifyHolder)
	local card = frame({
		Position = UDim2.fromOffset(310, 0), Size = UDim2.fromScale(1, 1), BackgroundColor3 = COL.Panel,
	}, slot)
	corner(card, CORNER)
	stroke(card, COL.White, 1, 0.7)
	frame({ Size = UDim2.new(0, 2, 1, 0), BackgroundColor3 = COL.White }, card)
	label({
		Position = UDim2.fromOffset(14, 8), Size = UDim2.new(1, -22, 0, 16), Text = title,
		Font = Enum.Font.GothamBold, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
	}, card)
	label({
		Position = UDim2.fromOffset(14, 26), Size = UDim2.new(1, -22, 0, 22), Text = text,
		TextSize = 12, TextColor3 = COL.Sub, TextXAlignment = Enum.TextXAlignment.Left,
		TextWrapped = true, TextYAlignment = Enum.TextYAlignment.Top,
	}, card)
	tween(card, 0.25, { Position = UDim2.fromOffset(0, 0) })
	task.delay(duration or 3, function()
		if card.Parent then
			tween(card, 0.25, { Position = UDim2.fromOffset(310, 0) })
			task.wait(0.3)
			slot:Destroy()
		end
	end)
end

local tabs, order = {}, {}

local function selectTab(name)
	for n, t in pairs(tabs) do
		local on = (n == name)
		if on and not t.page.Visible then
			t.page.Position = UDim2.fromOffset(0, 12)
			tween(t.page, 0.22, { Position = UDim2.fromOffset(0, 0) })
		end
		t.page.Visible = on
		t.active = on
		tween(t.button, 0.15, { BackgroundTransparency = on and 0 or 1, BackgroundColor3 = COL.Element })
		tween(t.indicator, 0.15, { BackgroundTransparency = on and 0 or 1 })
		tween(t.text, 0.15, { TextColor3 = on and COL.White or COL.Sub })
	end
	Crumb.Text = string.format(
		'<font color="rgb(125,125,125)">wexst\'s flsn  /  </font>%s', string.lower(name)
	)
end

local function CreateTab(name, raw)
	local btn = button({
		Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = COL.Element, BackgroundTransparency = 1,
	}, TabList)
	corner(btn, CORNER)
	local ind = frame({
		AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.new(0, 2, 0.6, 0), BackgroundColor3 = COL.White, BackgroundTransparency = 1,
	}, btn)
	local txt = label({
		Position = UDim2.fromOffset(16, 0), Size = UDim2.new(1, -16, 1, 0), Text = name,
		Font = Enum.Font.GothamMedium, TextColor3 = COL.Sub, TextXAlignment = Enum.TextXAlignment.Left,
	}, btn)

	local page, columns
	if raw then
		page = build("Frame", {
			Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false,
		}, {}, PageHolder)
		pad(page, 10)
	else
		page = build("ScrollingFrame", {
			Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0,
			ScrollBarThickness = 3, ScrollBarImageColor3 = COL.White, ScrollBarImageTransparency = 0.5,
			CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
			ScrollingDirection = Enum.ScrollingDirection.Y, Visible = false,
		}, {}, PageHolder)
		pad(page, 14)

		local function column(xScale, xOffset)
			local c = frame({
				Position = UDim2.new(xScale, xOffset, 0, 0), Size = UDim2.new(0.5, -7, 0, 0),
				AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
			}, page)
			listLayout(c, 12)
			return c
		end
		columns = { column(0, 0), column(0.5, 7) }
	end

	local tab = { page = page, button = btn, indicator = ind, text = txt, active = false }
	tabs[name] = tab
	table.insert(order, name)

	btn.MouseEnter:Connect(function()
		if not tab.active then tween(btn, 0.12, { BackgroundTransparency = 0.6 }) end
	end)
	btn.MouseLeave:Connect(function()
		if not tab.active then tween(btn, 0.12, { BackgroundTransparency = 1 }) end
	end)
	btn.MouseButton1Click:Connect(function() selectTab(name) end)

	function tab:Section(title, col)
		local card = frame({
			Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = COL.Card,
		}, columns[col or 1])
		corner(card, CORNER)
		stroke(card, COL.Line, 1, 0)
		pad(card, 12)
		listLayout(card, 8)

		label({
			Size = UDim2.new(1, 0, 0, 14), Text = string.upper(title), Font = Enum.Font.GothamBold,
			TextSize = 11, TextColor3 = COL.Sub, TextXAlignment = Enum.TextXAlignment.Left,
		}, card)
		frame({ Size = UDim2.new(1, 0, 0, 1), BackgroundColor3 = COL.Line }, card)

		local S = {}

		function S:Label(text)
			local l = label({
				Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = text,
				TextSize = 12, TextColor3 = COL.Sub, TextXAlignment = Enum.TextXAlignment.Left,
				TextWrapped = true,
			}, card)
			return { Set = function(_, t) l.Text = t end }
		end

		function S:Info(key, value)
			local row = frame({ Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1 }, card)
			label({
				Size = UDim2.new(0.5, 0, 1, 0), Text = key, TextSize = 12, TextColor3 = COL.Sub,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, row)
			local v = label({
				AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.new(0.5, 0, 1, 0),
				Text = value, Font = Enum.Font.Code, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			return { Set = function(_, t) v.Text = t end }
		end

		function S:Button(text, cb)
			local b = button({
				Size = UDim2.new(1, 0, 0, 30), Text = text, TextSize = 12,
			}, card)
			corner(b, CORNER)
			local st = stroke(b, COL.White, 1, 0.85)
			b.MouseEnter:Connect(function()
				tween(b, 0.12, { BackgroundColor3 = COL.Hover })
				tween(st, 0.12, { Transparency = 0.45 })
			end)
			b.MouseLeave:Connect(function()
				tween(b, 0.12, { BackgroundColor3 = COL.Element })
				tween(st, 0.12, { Transparency = 0.85 })
			end)
			b.MouseButton1Click:Connect(function()
				b.BackgroundColor3 = COL.White
				b.TextColor3 = COL.Black
				tween(b, 0.25, { BackgroundColor3 = COL.Hover, TextColor3 = COL.Text })
				if cb then task.spawn(cb) end
			end)
		end

		function S:Toggle(text, default, cb)
			local state = default and true or false
			local row = button({ Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1 }, card)
			local lbl = label({
				Size = UDim2.new(1, -30, 1, 0), Text = text, TextSize = 13,
				TextColor3 = state and COL.White or COL.Text, TextXAlignment = Enum.TextXAlignment.Left,
			}, row)
			local box = frame({
				AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0),
				Size = UDim2.fromOffset(18, 18), BackgroundColor3 = COL.Element,
			}, row)
			corner(box, 3)
			stroke(box, COL.White, 1, 0.6)
			local fill = frame({
				AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
				Size = UDim2.fromOffset(state and 10 or 0, state and 10 or 0), BackgroundColor3 = COL.White,
			}, box)
			corner(fill, 2)

			local function render()
				local s = state and 10 or 0
				tween(fill, 0.12, { Size = UDim2.fromOffset(s, s) })
				tween(lbl, 0.12, { TextColor3 = state and COL.White or COL.Text })
			end
			local function set(v, silent)
				state = v
				render()
				if cb and not silent then task.spawn(cb, state) end
			end
			row.MouseButton1Click:Connect(function() set(not state) end)
			return { Set = function(_, v) set(v) end }
		end

		function S:Slider(text, min, max, default, cb)
			local value = default or min
			local row = frame({ Size = UDim2.new(1, 0, 0, 40), BackgroundTransparency = 1 }, card)
			label({
				Size = UDim2.new(1, -60, 0, 16), Text = text, TextXAlignment = Enum.TextXAlignment.Left,
			}, row)
			local valLbl = label({
				AnchorPoint = Vector2.new(1, 0), Position = UDim2.fromScale(1, 0), Size = UDim2.fromOffset(60, 16),
				Font = Enum.Font.Code, TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right,
			}, row)
			local hit = button({
				Position = UDim2.fromOffset(0, 22), Size = UDim2.new(1, 0, 0, 16), BackgroundTransparency = 1,
			}, row, true)
			local bar = frame({
				AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.fromScale(0, 0.5),
				Size = UDim2.new(1, 0, 0, 4), BackgroundColor3 = COL.Element,
			}, hit)
			corner(bar, 2)
			local fill = frame({ Size = UDim2.fromScale(0, 1), BackgroundColor3 = COL.White }, bar)
			corner(fill, 2)
			frame({
				AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(1, 0.5),
				Size = UDim2.fromOffset(8, 12), BackgroundColor3 = COL.White, ZIndex = 2,
			}, fill)

			local lastValue = value
			local function set(v)
				value = math.clamp(math.floor(v + 0.5), min, max)
				fill.Size = UDim2.fromScale((value - min) / (max - min), 1)
				valLbl.Text = tostring(value)
				if value ~= lastValue then
					lastValue = value
					playSlider()
				end
				if cb then task.spawn(cb, value) end
			end
			fill.Size = UDim2.fromScale((value - min) / (max - min), 1)
			valLbl.Text = tostring(value)

			local sliding = false
			local function fromInput(input)
				local rel = (input.Position.X - bar.AbsolutePosition.X) / bar.AbsoluteSize.X
				set(min + (max - min) * math.clamp(rel, 0, 1))
			end
			hit.InputBegan:Connect(function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
					sliding = true
					fromInput(i)
				end
			end)
			connect(UIS.InputEnded, function(i)
				if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
					sliding = false
				end
			end)
			connect(UIS.InputChanged, function(i)
				if sliding and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
					fromInput(i)
				end
			end)
		end

		function S:Dropdown(text, options, default, cb)
			local current = default or options[1]
			local box = frame({
				Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
			}, card)
			listLayout(box, 4)
			local head = button({ Size = UDim2.new(1, 0, 0, 30) }, box)
			corner(head, CORNER)
			stroke(head, COL.White, 1, 0.85)
			local headText = label({
				Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -34, 1, 0), TextSize = 12,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, head)
			local arrow = label({
				AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 0), Size = UDim2.fromOffset(14, 30),
				Text = "+", Font = Enum.Font.Code, TextSize = 14, TextColor3 = COL.Sub,
			}, head)
			local function refresh()
				headText.Text = text .. '  <font color="rgb(125,125,125)">' .. tostring(current) .. "</font>"
			end
			headText.RichText = true
			refresh()

			local list = frame({
				Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
				BackgroundColor3 = COL.Element, Visible = false,
			}, box)
			corner(list, CORNER)
			listLayout(list, 0)
			for _, opt in ipairs(options) do
				local ob = button({
					Size = UDim2.new(1, 0, 0, 26), BackgroundColor3 = COL.Element, BackgroundTransparency = 1,
					Text = tostring(opt), TextSize = 12, TextColor3 = COL.Text,
				}, list)
				ob.MouseEnter:Connect(function() tween(ob, 0.1, { BackgroundTransparency = 0, BackgroundColor3 = COL.Hover }) end)
				ob.MouseLeave:Connect(function() tween(ob, 0.1, { BackgroundTransparency = 1 }) end)
				ob.MouseButton1Click:Connect(function()
					current = opt
					refresh()
					list.Visible = false
					arrow.Text = "+"
					if cb then task.spawn(cb, current) end
				end)
			end
			head.MouseButton1Click:Connect(function()
				list.Visible = not list.Visible
				arrow.Text = list.Visible and "-" or "+"
			end)
		end

		function S:Keybind(text, default, cb)
			local key = default
			local binding = false
			local row = frame({ Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1 }, card)
			label({
				Size = UDim2.new(1, -90, 1, 0), Text = text, TextXAlignment = Enum.TextXAlignment.Left,
			}, row)
			local kb = button({
				AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(80, 22),
				Text = key.Name, Font = Enum.Font.Code, TextSize = 11,
			}, row)
			corner(kb, 3)
			stroke(kb, COL.White, 1, 0.8)
			kb.MouseButton1Click:Connect(function()
				binding = true
				kb.Text = "..."
			end)
			connect(UIS.InputBegan, function(input, processed)
				if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
				if binding then
					binding = false
					if input.KeyCode ~= Enum.KeyCode.Escape then key = input.KeyCode end
					kb.Text = key.Name
				elseif not processed and input.KeyCode == key then
					if cb then task.spawn(cb, key) end
				end
			end)
		end

		function S:TextBox(placeholder, cb)
			local tb = build("TextBox", {
				Size = UDim2.new(1, 0, 0, 30), BackgroundColor3 = COL.Element, BorderSizePixel = 0,
				Text = "", PlaceholderText = placeholder, PlaceholderColor3 = COL.Sub,
				TextColor3 = COL.Text, Font = Enum.Font.Gotham, TextSize = 12, ClearTextOnFocus = false,
				TextXAlignment = Enum.TextXAlignment.Left,
			}, {}, card)
			corner(tb, CORNER)
			pad(tb, 8)
			local st = stroke(tb, COL.White, 1, 0.85)
			tb.Focused:Connect(function() tween(st, 0.12, { Transparency = 0.4 }) end)
			tb.FocusLost:Connect(function(enter)
				tween(st, 0.12, { Transparency = 0.85 })
				if cb then task.spawn(cb, tb.Text, enter) end
			end)
		end

		return S
	end

	return tab
end

