local clip = setclipboard or toclipboard

do
local ASSET_TYPES = {
	[1] = "Image", [2] = "T-Shirt", [3] = "Audio", [4] = "Mesh", [5] = "Lua", [8] = "Hat", [9] = "Place",
	[10] = "Model", [11] = "Shirt", [12] = "Pants", [13] = "Decal", [17] = "Head", [18] = "Face",
	[19] = "Gear", [21] = "Badge", [24] = "Animation", [32] = "Package", [34] = "GamePass",
	[40] = "MeshPart", [41] = "Hair Accessory", [42] = "Face Accessory", [43] = "Neck Accessory",
	[44] = "Shoulder Accessory", [45] = "Front Accessory", [46] = "Back Accessory", [47] = "Waist Accessory",
}

local ASSET_PROPS = {
	Decal = { "Texture" }, Texture = { "Texture" }, ImageLabel = { "Image" },
	ImageButton = { "Image", "HoverImage", "PressedImage" }, Sound = { "SoundId" },
	MeshPart = { "MeshId", "TextureID" }, SpecialMesh = { "MeshId", "TextureId" },
	Shirt = { "ShirtTemplate" }, Pants = { "PantsTemplate" }, ShirtGraphic = { "Graphic" },
	Animation = { "AnimationId" }, ParticleEmitter = { "Texture" }, Beam = { "Texture" }, Trail = { "Texture" },
	Sky = { "SkyboxBk", "SkyboxDn", "SkyboxFt", "SkyboxLf", "SkyboxRt", "SkyboxUp" },
	SurfaceAppearance = { "ColorMap", "NormalMap", "MetalnessMap", "RoughnessMap" },
	Tool = { "TextureId" },
}

local function idPattern(id)
	return "%f[%d]" .. id .. "%f[%D]"
end

local function scanRoots()
	local r = {
		workspace, Lighting, game:GetService("ReplicatedStorage"), game:GetService("StarterGui"),
		game:GetService("StarterPack"), game:GetService("SoundService"), game:GetService("ReplicatedFirst"),
	}
	local pg = LocalPlayer:FindFirstChildOfClass("PlayerGui")
	if pg then table.insert(r, pg) end
	return r
end

local function findUses(id)
	local out, pat, n = {}, idPattern(id), 0
	for _, root in ipairs(scanRoots()) do
		for _, inst in ipairs(root:GetDescendants()) do
			local props = ASSET_PROPS[inst.ClassName]
			if props and not inst:IsDescendantOf(Gui) then
				for _, p in ipairs(props) do
					local ok, v = pcall(function() return inst[p] end)
					if ok and type(v) == "string" and string.find(v, pat) then
						table.insert(out, { inst = inst, prop = p })
					end
				end
			end
			n += 1
			if n % 4000 == 0 then task.wait() end
		end
	end
	return out
end

local function getAssetInfo(id)
	local ok, info = pcall(function() return MarketplaceService:GetProductInfo(tonumber(id), Enum.InfoType.Asset) end)
	if not ok or type(info) ~= "table" then return nil end
	return {
		kind = ASSET_TYPES[info.AssetTypeId] or ("Type " .. tostring(info.AssetTypeId)),
		name = info.Name or "?",
		creator = info.Creator and info.Creator.Name or "?",
	}
end

local AITab = CreateTab("AI", true)
local aiPage = AITab.page
local aiState, aiCurrent, aiBusy = "target", nil, false
local aiRecords = {}
local msgOrder = 0

local chatBox = frame({ Size = UDim2.new(1, 0, 1, -76), BackgroundColor3 = COL.Card }, aiPage)
corner(chatBox, CORNER)
stroke(chatBox, COL.Line, 1, 0)

local chatLog = build("ScrollingFrame", {
	Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, BorderSizePixel = 0,
	ScrollBarThickness = 3, ScrollBarImageColor3 = COL.White, ScrollBarImageTransparency = 0.5,
	CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.Y,
	ScrollingDirection = Enum.ScrollingDirection.Y,
}, {}, chatBox)
pad(chatLog, 10)
listLayout(chatLog, 6)

local scriptView = build("ScrollingFrame", {
	Size = UDim2.new(1, 0, 1, -76), BackgroundColor3 = COL.Bg, BorderSizePixel = 0, Visible = false,
	ScrollBarThickness = 3, ScrollBarImageColor3 = COL.White, ScrollBarImageTransparency = 0.5,
	CanvasSize = UDim2.new(), AutomaticCanvasSize = Enum.AutomaticSize.XY,
	ScrollingDirection = Enum.ScrollingDirection.XY,
}, {}, aiPage)
corner(scriptView, CORNER)
