	Size = UDim2.fromOffset(0, 0), AutomaticSize = Enum.AutomaticSize.XY, Font = Enum.Font.Code,
	TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top,
}, scriptView)

local function addMsg(text, fromUser)
	msgOrder += 1
	label({
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Text = text, Font = Enum.Font.Code,
		TextSize = 12, TextColor3 = fromUser and COL.White or COL.Sub, TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top, LayoutOrder = msgOrder,
	}, chatLog)
	task.delay(0.05, function()
		chatLog.CanvasPosition = Vector2.new(0, 1e5)
	end)
end

local scriptShown = false
local scriptBtn

local function setScriptView(on)
	scriptShown = on
	scriptView.Visible = on
	chatBox.Visible = not on
	if scriptBtn then scriptBtn.Text = on and "Chat" or "Script" end
end

local function buildScript()
	local keys = {}
	for k in pairs(ASSET_PROPS) do keys[#keys + 1] = k end
	table.sort(keys)
	local out = { "local MAP = {" }
	for _, r in ipairs(aiRecords) do
		out[#out + 1] = string.format('\t["%s"] = "%s",', r.old, r.new)
	end
	out[#out + 1] = "}"
	out[#out + 1] = ""
	out[#out + 1] = "local PROPS = {"
	for _, k in ipairs(keys) do
		local ps = {}
		for _, p in ipairs(ASSET_PROPS[k]) do ps[#ps + 1] = '"' .. p .. '"' end
		out[#out + 1] = string.format("\t%s = { %s },", k, table.concat(ps, ", "))
	end
	out[#out + 1] = "}"
	out[#out + 1] = [==[

local function fix(inst)
	local props = PROPS[inst.ClassName]
	if not props then return end
	for _, p in ipairs(props) do
		local ok, v = pcall(function() return inst[p] end)
		if ok and type(v) == "string" then
			local nv = v
			for old, new in pairs(MAP) do
				nv = nv:gsub("%f[%d]" .. old .. "%f[%D]", new)
			end
			if nv ~= v then pcall(function() inst[p] = nv end) end
		end
	end
end

local roots = {
	workspace, game:GetService("Lighting"), game:GetService("ReplicatedStorage"),
	game:GetService("StarterGui"), game:GetService("SoundService"),
}
local pg = game:GetService("Players").LocalPlayer:FindFirstChildOfClass("PlayerGui")
if pg then table.insert(roots, pg) end

for _, root in ipairs(roots) do
	for _, d in ipairs(root:GetDescendants()) do fix(d) end
	root.DescendantAdded:Connect(fix)
end]==]
	return table.concat(out, "\n")
end

local function showScript()
	if #aiRecords == 0 then
		addMsg("Nothing to build yet. Send an ID and a replacement first.")
		return
	end
	local code = buildScript()
	scriptText.Text = code
	setScriptView(true)
	local msg = "Script ready"
	if clip then
		pcall(clip, code)
		msg = "Script copied to clipboard"
	end
	if writefile then
		pcall(writefile, "wexst_replace.lua", code)
		msg = msg .. ", saved as wexst_replace.lua"
	end
	Notify("Wexst's FLSN", msg, 3)
end

local function undoLast()
	if aiState == "replace" then
		aiState, aiCurrent = "target", nil
		addMsg("Cancelled.")
		return
	end
	local rec = table.remove(aiRecords)
	if not rec then
		addMsg("Nothing to undo.")
		return
	end
	for _, c in ipairs(rec.changes) do
		pcall(function() c.inst[c.prop] = c.old end)
	end
	addMsg(("Undid %s -> %s (%d restored)."):format(rec.old, rec.new, #rec.changes))
end

local function clearChat()
	for _, c in ipairs(chatLog:GetChildren()) do
		if c:IsA("TextLabel") then c:Destroy() end
	end
end

local function lookupId(id)
	aiBusy = true
	local info = getAssetInfo(id)
	local uses = findUses(id)
	if info then
		addMsg(("%s  |  %s  |  %s  |  by %s"):format(id, info.kind, info.name, info.creator))
	else
		addMsg(id .. "  |  couldn't get info (private, removed, or not an asset)")
	end
	if #uses > 0 then
		addMsg(("Used %d time(s) in this game. Send the replacement ID, or skip."):format(#uses))
	else
		addMsg("Not used anywhere right now. You can still send a replacement and it goes in the script.")
	end
	aiCurrent = { id = id, uses = uses, kind = info and info.kind or nil }
	aiState = "replace"
	aiBusy = false
end

local function replaceId(newId)
	aiBusy = true
	local info = getAssetInfo(newId)
	if info then
		addMsg(("%s  |  %s  |  %s"):format(newId, info.kind, info.name))
		if aiCurrent.kind and info.kind ~= aiCurrent.kind then
			addMsg(("Heads up: that is a %s, the original was a %s."):format(info.kind, aiCurrent.kind))
		end
	end
	local pat = idPattern(aiCurrent.id)
	local changes = {}
	for _, u in ipairs(aiCurrent.uses) do
		if u.inst.Parent then
			local ok, cur = pcall(function() return u.inst[u.prop] end)
			if ok and type(cur) == "string" then
				local nv = (cur:gsub(pat, newId))
				if pcall(function() u.inst[u.prop] = nv end) then
					table.insert(changes, { inst = u.inst, prop = u.prop, old = cur })
				end
			end
		end
	end
	table.insert(aiRecords, { old = aiCurrent.id, new = newId, changes = changes })
	addMsg(("Replaced %d: %s -> %s. Send another ID, or press Script."):format(#changes, aiCurrent.id, newId))
	aiState, aiCurrent = "target", nil
	aiBusy = false
end

local function handleInput(text)
	text = text:gsub("^%s+", ""):gsub("%s+$", "")
	if text == "" then return end
	if scriptShown then setScriptView(false) end
	addMsg("> " .. text, true)
	local lower = text:lower()
	if lower == "script" then showScript() return end
	if lower == "undo" then undoLast() return end
	if lower == "clear" then clearChat() return end
	if aiBusy then addMsg("Still working on the last one.") return end
	if aiState == "replace" and (lower == "skip" or lower == "no") then
		aiState, aiCurrent = "target", nil
		addMsg("Skipped. Send the next ID.")
		return
	end
	local id = text:match("%d+")
	if not id then
		addMsg("Send an asset ID. Commands: script, undo, clear.")
		return
	end
	if aiState == "target" then
		task.spawn(lookupId, id)
	else
		task.spawn(replaceId, id)
	end
end

