local dump
task.spawn(function()
	local ok, body = pcall(function()
		return game:HttpGet("https://raw.githubusercontent.com/MaximumADHD/Roblox-Client-Tracker/roblox/API-Dump.json")
	end)
	if not ok or type(body) ~= "string" then return end
	local ok2, data = pcall(function() return HttpService:JSONDecode(body) end)
	if not ok2 or type(data) ~= "table" or not data.Classes then return end
	local classes = {}
	for _, c in ipairs(data.Classes) do classes[c.Name] = c end
	dump = classes
end)

local function propsFromDump(inst)
	local list, seen = {}, {}
	local cn = inst.ClassName
	if not dump[cn] then return nil end
	while cn and dump[cn] do
		local c = dump[cn]
		for _, m in ipairs(c.Members) do
			if m.MemberType == "Property" and not seen[m.Name] then
				local sec = m.Security
				local readable = (type(sec) == "string" and sec == "None") or (type(sec) == "table" and sec.Read == "None")
				local hidden = false
				if m.Tags then
					for _, t in ipairs(m.Tags) do
						if t == "Hidden" or t == "NotScriptable" or t == "Deprecated" then hidden = true end
					end
				end
				if readable and not hidden then
					seen[m.Name] = true
					list[#list + 1] = m.Name
				end
			end
		end
		cn = c.Superclass
	end
	table.sort(list)
	for i, n in ipairs(list) do
		if n == "Name" then
			table.remove(list, i)
			table.insert(list, 1, "Name")
			break
		end
	end
	return list
end

local function propsFor(inst)
	if dump then
		local l = propsFromDump(inst)
		if l then return l end
	end
	local out, seen = {}, {}
	for _, entry in ipairs(CURATED) do
		if inst:IsA(entry[1]) then
			for _, p in ipairs(entry[2]) do
				if not seen[p] then
					seen[p] = true
					out[#out + 1] = p
				end
			end
		end
	end
	return out
end

local function fmt(v)
	local t = typeof(v)
	if t == "Color3" then
		return string.format("%d, %d, %d", math.floor(v.R * 255 + 0.5), math.floor(v.G * 255 + 0.5), math.floor(v.B * 255 + 0.5))
	elseif t == "Instance" then
		return v:GetFullName()
	elseif t == "EnumItem" then
		return v.Name
	elseif t == "number" then
		return tostring(math.floor(v * 1000 + 0.5) / 1000)
	end
	return tostring(v)
end

local function parseValue(old, text)
	local t = typeof(old)
	if t == "string" then
		return true, text
	elseif t == "number" then
		local n = tonumber(text)
		return n ~= nil, n
	elseif t == "boolean" then
		local l = text:lower()
		if l == "true" then return true, true end
		if l == "false" then return true, false end
		return false
	elseif t == "EnumItem" then
		for _, item in ipairs(old.EnumType:GetEnumItems()) do
			if item.Name:lower() == text:lower() then return true, item end
		end
		return false
	end
	local parts = {}
	for p in text:gmatch("[^,]+") do parts[#parts + 1] = tonumber(p) end
	if t == "Vector3" and #parts == 3 and parts[1] and parts[2] and parts[3] then
		return true, Vector3.new(parts[1], parts[2], parts[3])
	elseif t == "Vector2" and #parts == 2 and parts[1] and parts[2] then
		return true, Vector2.new(parts[1], parts[2])
	elseif t == "Color3" and #parts == 3 and parts[1] and parts[2] and parts[3] then
		return true, Color3.fromRGB(parts[1], parts[2], parts[3])
	end
	return false
end

local exRoot = game
local expanded = { [workspace] = true }
local flat = {}
local selected
local searchText = ""
local lastClickInst, lastClickT = nil, 0
local viewRows = {}
local render, rebuild, toggle, selectInst, openScript

local function showProps(inst)
	for _, c in ipairs(propList:GetChildren()) do
		if c:IsA("Frame") then c:Destroy() end
	end
	if not inst then
		propTitle.Text = "Properties"
		return
	end
	propTitle.Text = "Properties  /  " .. inst.ClassName .. "  /  " .. inst.Name
	local names = propsFor(inst)
	for i, pname in ipairs(names) do
		if i > 140 then break end
		local ok, val = pcall(function() return inst[pname] end)
		if ok then
			local row = frame({ Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1, LayoutOrder = i }, propList)
			label({
				Position = UDim2.fromOffset(10, 0), Size = UDim2.new(0.42, -10, 1, 0), Text = pname, TextSize = 12,
				TextColor3 = COL.Sub, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd,
			}, row)
			local editable = EDITABLE[typeof(val)] and pname ~= "ClassName" or false
			local tb = build("TextBox", {
				Position = UDim2.new(0.42, 0, 0, 1), Size = UDim2.new(0.58, -8, 1, -2),
				BackgroundColor3 = COL.Element, BackgroundTransparency = editable and 0 or 1, BorderSizePixel = 0,
				Text = fmt(val), TextColor3 = editable and COL.White or COL.Text, Font = Enum.Font.Code, TextSize = 11,
				TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, TextEditable = editable,
				TextTruncate = Enum.TextTruncate.AtEnd,
			}, {}, row)
			padX(tb, 6)
			corner(tb, 3)
			if editable then
				tb.FocusLost:Connect(function()
					local okc, cur = pcall(function() return inst[pname] end)
					local okp, nv = parseValue(okc and cur or val, tb.Text)
					if okp then
						if not pcall(function() inst[pname] = nv end) then
							Notify("Wexst's FLSN", "Couldn't set " .. pname, 2)
						end
					end
					local okr, now = pcall(function() return inst[pname] end)
					if okr then tb.Text = fmt(now) end
					if pname == "Name" then render() end
				end)
			end
		end
	end
end

local function getSource(s)
	local ok, src = pcall(function() return s.Source end)
	if ok and type(src) == "string" and src ~= "" then return src end
	if decompile then
		local ok2, res = pcall(decompile, s)
		if ok2 and type(res) == "string" and res ~= "" then return res end
	end
	return "-- couldn't read this script (server scripts aren't visible to the client, or the executor has no decompiler)"
end

openScript = function(inst)
	editorTitle.Text = "Script  /  " .. inst:GetFullName()
	local src = getSource(inst)
	if #src > 120000 then src = src:sub(1, 120000) .. "\n-- truncated" end
	codeBox.Text = src
	codeScroll.CanvasPosition = Vector2.new(0, 0)
end

local function cmp(a, b)
	local an, bn = a.Name:lower(), b.Name:lower()
	if an ~= bn then return an < bn end
	return a.ClassName < b.ClassName
end

rebuild = function()
	table.clear(flat)
	if searchText ~= "" then
		local q = searchText:lower()
		local n = 0
		for _, d in ipairs(exRoot:GetDescendants()) do
			if d.Name:lower():find(q, 1, true) then
				n += 1
				flat[n] = { inst = d, depth = 0 }
				if n >= 400 then break end
			end
		end
	else
		local function walk(inst, depth)
			local kids = inst:GetChildren()
			table.sort(kids, cmp)
			for _, k in ipairs(kids) do
				flat[#flat + 1] = { inst = k, depth = depth }
				if expanded[k] then walk(k, depth + 1) end
			end
		end
		walk(exRoot, 0)
	end
	tree.CanvasSize = UDim2.fromOffset(0, #flat * ROW + 4)
end

local function isScript(inst)
	return inst:IsA("LuaSourceContainer")
end

for i = 1, POOL do
	local btn = build("TextButton", {
		Size = UDim2.new(1, 0, 0, ROW), BackgroundColor3 = COL.Hover, BackgroundTransparency = 1,
		BorderSizePixel = 0, Text = "", AutoButtonColor = false, Visible = false,
	}, {}, tree)
	local arrow = build("TextButton", {
		Size = UDim2.fromOffset(14, ROW), BackgroundTransparency = 1, BorderSizePixel = 0, Text = "",
		Font = Enum.Font.Code, TextSize = 12, TextColor3 = COL.Sub, AutoButtonColor = false, ZIndex = 2,
	}, {}, btn)
	local badge = frame({ Size = UDim2.fromOffset(14, 14), BackgroundColor3 = COL.Element }, btn)
	corner(badge, 3)
	local letter = label({
		Size = UDim2.fromScale(1, 1), Font = Enum.Font.GothamBold, TextSize = 9, TextColor3 = COL.Text,
	}, badge)
	local nameLbl = label({
		Size = UDim2.new(1, -40, 1, 0), TextSize = 12, TextXAlignment = Enum.TextXAlignment.Left,
		TextTruncate = Enum.TextTruncate.AtEnd,
	}, btn)
	local r = { btn = btn, arrow = arrow, badge = badge, letter = letter, name = nameLbl }
	viewRows[i] = r

	arrow.MouseButton1Click:Connect(function()
		if r.item and searchText == "" then toggle(r.item.inst) end
	end)
	btn.MouseButton1Click:Connect(function()
		local item = r.item
		if not item then return end
		playClick()
		local inst = item.inst
		local now = os.clock()
		if lastClickInst == inst and now - lastClickT < 0.4 then
			lastClickInst = nil
			if isScript(inst) then
				openScript(inst)
			elseif searchText == "" then
				toggle(inst)
			end
		else
			lastClickInst, lastClickT = inst, now
		end
		selectInst(inst)
	end)
end

render = function()
	local first = math.floor(tree.CanvasPosition.Y / ROW) + 1
	for i, r in ipairs(viewRows) do
		local idx = first + i - 1
		local item = flat[idx]
		r.item = item
		if item then
			local inst, depth = item.inst, item.depth
			local x = 4 + depth * 12
			r.btn.Visible = true
			r.btn.Position = UDim2.fromOffset(0, (idx - 1) * ROW)
			r.btn.BackgroundTransparency = (inst == selected) and 0 or 1
			local hasKids = searchText == "" and inst:GetChildren()[1] ~= nil
			r.arrow.Position = UDim2.fromOffset(x, 0)
			r.arrow.Text = hasKids and (expanded[inst] and "v" or ">") or ""
			r.badge.Position = UDim2.fromOffset(x + 16, 3)
			local script = isScript(inst)
			r.badge.BackgroundColor3 = script and COL.White or COL.Element
			r.letter.TextColor3 = script and COL.Black or COL.Text
			r.letter.Text = inst.ClassName:sub(1, 1)
			r.name.Position = UDim2.fromOffset(x + 36, 0)
			r.name.Text = inst.Name
			r.name.TextColor3 = (inst == selected) and COL.White or COL.Text
		else
			r.btn.Visible = false
		end
	end
end

toggle = function(inst)
	expanded[inst] = not expanded[inst]
	rebuild()
	render()
end

selectInst = function(inst)
	selected = inst
	render()
	showProps(inst)
end

tree:GetPropertyChangedSignal("CanvasPosition"):Connect(render)

local searchToken = 0
searchBox:GetPropertyChangedSignal("Text"):Connect(function()
	searchToken += 1
	local mine = searchToken
	task.delay(0.35, function()
		if mine ~= searchToken then return end
		searchText = searchBox.Text
		rebuild()
		tree.CanvasPosition = Vector2.new(0, 0)
		render()
	end)
end)

toolBtn("Refresh", function()
	rebuild()
	render()
	showProps(selected)
end)
toolBtn("Path", function()
	if selected and clip then
		pcall(clip, selected:GetFullName())
		Notify("Wexst's FLSN", "Path copied", 2)
	end
end)
toolBtn("Delete", function()
	if selected then
		pcall(function() selected:Destroy() end)
		selected = nil
		showProps(nil)
		rebuild()
		render()
	end
end)
toolBtn("Open", function()
	if selected and isScript(selected) then
		openScript(selected)
	else
		Notify("Wexst's FLSN", "Select a script first", 2)
	end
end)

rebuild()
render()

end
end

