ui:Toggle("UI Glow", true, function(v) glowOn = v end)
local danger = SettingsTab:Section("Danger Zone", 1)
danger:Button("Destroy GUI", destroyAll)

local atmo = SettingsTab:Section("Atmosphere", 2)
atmo:Toggle("Snow", true, function(v) snowEnabled = v end)
atmo:Slider("Snow Amount", 10, MAX_FLAKES, 110, function(v) snowCount = v end)
atmo:Slider("Wind", 0, 200, 100, function(v) windScale = v / 100 end)
atmo:Toggle("Background Blur", true, function(v) blurEnabled = v; applyBackdrop(hubShown) end)
atmo:Slider("Blur Strength", 0, 24, 12, function(v) blurStrength = v; if hubShown then applyBackdrop(true) end end)
atmo:Toggle("Dim Background", true, function(v) dimOn = v; applyBackdrop(hubShown) end)

selectTab("Home")

local SQ = 54
local sqPos = Vector2.new(60, 180)

local Squircle = frame({
	Name = "Squircle", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(sqPos.X, sqPos.Y),
	Size = UDim2.fromOffset(SQ, SQ), BackgroundTransparency = 1, Visible = false, ZIndex = 4,
}, Gui)
local SqScale = build("UIScale", { Scale = 0.001 }, {}, Squircle)

local sqGlow = frame({
	AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
	Size = UDim2.new(1, 12, 1, 12), BackgroundColor3 = COL.White, BackgroundTransparency = 0.9, ZIndex = 0,
}, Squircle)
corner(sqGlow, 18)
pulse(sqGlow, "BackgroundTransparency", 0.82, 0.1, 1.6, 0)

local SqBody = frame({ Size = UDim2.fromScale(1, 1), BackgroundColor3 = COL.Bg, ZIndex = 1 }, Squircle)
corner(SqBody, 14)
local sqStroke = stroke(SqBody, COL.White, 1.5, 0.4)
pulse(sqStroke, "Transparency", 0.2, 0.5, 1.6, 0.3)

local sqLogo = buildLogo(44, 44, SqBody, Enum.ScaleType.Crop)
sqLogo.AnchorPoint = Vector2.new(0.5, 0.5)
sqLogo.Position = UDim2.fromScale(0.5, 0.5)

local SqHit = button({
	Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, ZIndex = 10,
}, Squircle)

local busy, isOpen = false, true
local fit = 1

local function updateFit()
	local vp = Gui.AbsoluteSize
	fit = math.clamp(math.min(vp.X / (WIN_W + 40), vp.Y / (WIN_H + 40)), 0.4, 1)
	if isOpen and not busy then HubScale.Scale = fit end
end
connect(Gui:GetPropertyChangedSignal("AbsoluteSize"), updateFit)
updateFit()

local function closeHub()
	if busy or not isOpen then return end
	busy, isOpen = true, false
	hubShown = false
	applyBackdrop(false)
	local t = TweenService:Create(HubScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.In), { Scale = 0.001 })
	t:Play()
	t.Completed:Wait()
	Hub.Visible = false
	SqScale.Scale = 0.001
	Squircle.Visible = true
	local t2 = TweenService:Create(SqScale, TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = 1 })
	t2:Play()
	t2.Completed:Wait()
	busy = false
end

local function openHub()
	if busy or isOpen then return end
	busy, isOpen = true, true
	hubShown = true
	applyBackdrop(true)
	local t = TweenService:Create(SqScale, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = 0.001 })
	t:Play()
	t.Completed:Wait()
	Squircle.Visible = false
	HubScale.Scale = 0.001
	Hub.Visible = true
	local t2 = TweenService:Create(HubScale, TweenInfo.new(0.3, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = fit })
	t2:Play()
	t2.Completed:Wait()
	busy = false
end

CloseBtn.MouseButton1Click:Connect(closeHub)

do
	local dragging, moved, dragStart, startPos = false, false, nil, nil
	SqHit.InputBegan:Connect(function(input)
		if (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch) and not busy then
			dragging, moved = true, false
			dragStart = input.Position
			startPos = sqPos
			local c
			c = input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					c:Disconnect()
					dragging = false
					if not moved then openHub() end
				end
			end)
		end
	end)
	connect(UIS.InputChanged, function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local d = input.Position - dragStart
			if d.Magnitude > 4 then moved = true end
			if moved then
				local vp = Gui.AbsoluteSize
				local half = SQ / 2
				sqPos = Vector2.new(
					math.clamp(startPos.X + d.X, half, vp.X - half),
					math.clamp(startPos.Y + d.Y, half, vp.Y - half)
				)
				Squircle.Position = UDim2.fromOffset(sqPos.X, sqPos.Y)
			end
		end
	end)
end

do
	local frames, acc = 0, 0
	connect(RunService.Heartbeat, function(dt)
		local t = os.clock()
		for _, p in ipairs(pulses) do
			if glowOn then
				p.obj[p.prop] = p.base + p.amp * (0.5 + 0.5 * math.sin(t * p.speed + p.phase))
			else
				p.obj[p.prop] = p.base + p.amp
			end
		end
		Sweep.Visible = glowOn
		Sweep.Position = UDim2.fromOffset(((t * 190) % (CONTENT_W + 160)) - 140, 0)
		updateSnow(dt, t)

		frames = frames + 1
		acc = acc + dt
		if acc >= 0.5 then
			infoFps:Set(tostring(math.floor(frames / acc + 0.5)))
			local ok, ping = pcall(function() return LocalPlayer:GetNetworkPing() * 1000 end)
			infoPing:Set(ok and (math.floor(ping + 0.5) .. " ms") or "--")
			infoPlayers:Set(#Players:GetPlayers() .. " / " .. Players.MaxPlayers)
			Clock.Text = os.date("%H:%M")
			if gameLabel.Text ~= gameName then
				gameLabel.Text = gameName
				infoGame:Set(gameName)
			end
			frames, acc = 0, 0
		end
	end)
end

applyBackdrop(true)
Notify("Wexst's FLSN", "Loaded", 3)
